(()=>{var a=window.__goatcounterSite;if(a){let n=t=>{let o=t.closest(".article-views");if(o){o.setAttribute("hidden","hidden");return}if(t.classList.contains("goatcounter-views--total")){t.textContent="--";return}t.textContent="--"},c=async t=>{let o=t.getAttribute("data-goatcounter-path");if(!o){n(t);return}try{let e=await fetch(`${a}/counter/${encodeURIComponent(o)}.json`);if(!e.ok){n(t);return}let r=await e.json();if(typeof r?.count=="string"||typeof r?.count=="number"){t.textContent=String(r.count);return}n(t)}catch(e){console.warn("Failed to load GoatCounter count",e),n(t)}};document.querySelectorAll(".goatcounter-views").forEach(t=>{c(t)})}})();
